DROP DATABASE IF EXISTS quizbase;
CREATE DATABASE quizbase;
USE quizbase;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS responses;
DROP TABLE IF EXISTS options;
DROP TABLE IF EXISTS questions;
DROP TABLE IF EXISTS quizzes;
DROP TABLE IF EXISTS results;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS categories;
SET FOREIGN_KEY_CHECKS = 1;
CREATE TABLE categories (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL);
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(255) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(255) NOT NULL);
CREATE TABLE quizzes (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, category_id BIGINT NOT NULL, creator_id BIGINT NOT NULL, created_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE, FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE questions (id BIGINT PRIMARY KEY AUTO_INCREMENT, text VARCHAR(255) NOT NULL, quiz_id BIGINT NOT NULL, FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE options (id BIGINT PRIMARY KEY AUTO_INCREMENT, text VARCHAR(255) NOT NULL, is_correct BOOLEAN NOT NULL, question_id BIGINT NOT NULL, quiz_id BIGINT NOT NULL, FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE, FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE results (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, quiz_id BIGINT NOT NULL, score INT NOT NULL, attempted_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE responses (id BIGINT PRIMARY KEY AUTO_INCREMENT, question_id BIGINT NOT NULL, option_id BIGINT NOT NULL, result_id BIGINT NOT NULL, FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE, FOREIGN KEY (option_id) REFERENCES options(id) ON DELETE CASCADE, FOREIGN KEY (result_id) REFERENCES results(id) ON DELETE CASCADE);
